@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-app-shell {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr);
    min-block-size: 100dvh;
    background: var(--nz-app-shell-bg, var(--nz-bg-canvas));
    color: var(--nz-text-primary);
  }

  /* off-screen until focused, then over the page's top-start corner */
  .nz-app-shell-skip {
    position: fixed;
    inset-block-start: var(--nz-space-2);
    inset-inline-start: var(--nz-space-2);
    z-index: var(--nz-z-overlay);
    padding: var(--nz-space-2) var(--nz-space-3);
    border-radius: var(--nz-radius-md);
    background: var(--nz-bg-inverse);
    color: var(--nz-text-inverse);
    font: var(--nz-font-label-m-strong);
    letter-spacing: var(--nz-tracking-label-m-strong);
    text-decoration: none;
    translate: 0 calc(-100% - var(--nz-space-4));

    &:focus-visible {
      translate: none;
    }
  }

  .nz-app-shell-sidebar {
    grid-column: 1;
  }

  .nz-app-shell-frame {
    display: flex;
    grid-column: 2;
    flex-direction: column;
    min-inline-size: 0;
  }

  .nz-app-shell-main {
    flex: 1 1 auto;
    box-sizing: border-box;
    inline-size: 100%;
    max-inline-size: calc(var(--nz-layout-content-max) + 2 * var(--nz-grid-margin));
    margin-inline: auto;
    padding: var(--nz-app-shell-main-padding, var(--nz-section-gap) var(--nz-grid-margin));

    /* room for the tab bar below --nz-sm (the inset is 0 from there) */
    padding-block-end: calc(var(--nz-section-gap) + var(--nz-layout-bottom-inset, 0px));
    outline: none;
  }

  /* below --nz-sm: the MobileTopBar, and the MobileTabBar fixed to the bottom */
  .nz-app-shell-sidebar,
  .nz-app-shell-top-bar {
    display: none;
  }

  .nz-app-shell-tab-bar {
    position: fixed;
    inset-block-end: 0;
    inset-inline: 0;
    z-index: var(--nz-z-chrome);
  }

  /* from --nz-sm: the Sidebar and the TopBar */
  @media (--nz-sm) {
    .nz-app-shell-sidebar,
    .nz-app-shell-top-bar {
      display: block;
    }

    .nz-app-shell-mobile-top-bar,
    .nz-app-shell-tab-bar {
      display: none;
    }
  }
}
